close all
clearvars -except mapCD
fn = 'D:\od\OneDrive\matlab\RawData\1T-TaS2(point defect)\mapCD.mat';
loadif(fn); %[output:20ea1dd8] %[output:7f55cad5]

%%
%[text] ## Masked FFT filter
%[text] ### Create FFT mask
%[text] for iph = 1
iph = 1 %[output:9de9b51b]
mskTbl =table() %[output:6b268df2]

Z = mapCD.dt(iph).Z;
fZ = fft2(Z);
afZ = abs(fZ);

% mskTbl =table()
bin = afZ> 0.001*max(max(afZ)) %[output:905b95bb]
mskTbl = {bin,'2nd order peak visible histogram cut','too many aperiodic '} %[output:2af5a892]
mskTbl(2,:) = {R4fft(size(Z))>35,'kill low freq 35','still aperiodic term but better than 1st one'} %[output:9aa8b21e]
mskTbl(3,:) = {R4fft(size(Z))<130 'kill hi freq 1130' 'Maybe I focus on more than 2nd order peak, but high frequency does not affect to the result'} %[output:9093d2de]
mskTbl(4,:) = {mskTbl{2,1} & mskTbl{3,1},'ref 2,3 kill hi low','.'} %[output:12bf437a]
mskTbl(5,:) = {mskTbl{4,1}&mskTbl{1,1},'1 bas kill hi low','.'} %[output:5432bba2]
%%
%[text] for iph = 2
iph = 2 %[output:777eab90]
mskTbl =table() %[output:6353d625]

Z = mapCD.dt(iph).Z;
fZ = fft2(Z);
afZ = abs(fZ);

% mskTbl =table()
bin = afZ> 0.001*max(max(afZ)) %[output:616cb3a2]
mskTbl = {bin,'2nd order peak visible histogram cut','too many aperiodic '} %[output:8301217c]
%%
 
%%
%[text] ## Draw filtered result
groot().Children %[output:4b7d46b6]
%[text] Main function
msk = mskTbl(1,:) %[output:156ab959]
bin = msk{1};
[f,sbs] =  plt_Fourier_filtered_synthesis(Z,bin) %[output:35fc3007] %[output:86ac0592] %[output:54b7f010] %[output:1b7814fd] %[output:3cd1b436] %[output:737636f8] %[output:2e4afb09] %[output:002e35f4]
f.Visible = "on"
f.Position = [0 0 2000 1000]
%[text] colorlim modification
f.CurrentAxes = sbs(1,2)
climsc([0, 0.01]).Minmax
sbs(2,3).CLim = sbs(1,2).CLim
%%
se = strel('disk',2)
views(se.Neighborhood)
%[text] 4 or 5 mask filter
%%
%[text] ### 
%[text] 
function titlet(str)
title(str)
ax = gca;
ax.Tag = str;
end
%[text] 
function viewst(img)
views(fftshift(img))
end
%[text] 
function popViewst(bin)
f = figure(10)
views(fftshift(bin))
f.Visible = "on"
end


